let virtualGardenerState=null,virtualGardenerUser=null,virtualGardenerLoading=false;
const apiBeforeVirtual=api;
async function refreshVirtualFarm(){const uid=account?.id;if(!uid)return;const values=await Promise.all([apiBeforeVirtual('state'),apiBeforeVirtual('ops'),apiBeforeVirtual('lifecycle'),apiBeforeVirtual('batches'),apiBeforeVirtual('season')]);if(account?.id!==uid)return;cloud=values[0];opsData=values[1];lifeData=values[2];batchData=values[3].batches;if(batchData.some(b=>b.is_simulation)&&typeof storageDemoOverride!=='undefined')storageDemoOverride=false;seasonData=values[4]}
api=async function(action,body){const result=await apiBeforeVirtual(action,body);if(body&&account&&!action.startsWith('virtual-gardener')&&virtualGardenerUser===account.id&&virtualGardenerState?.enabled){try{const status=await apiBeforeVirtual('virtual-gardener-tick',{});if(status.enabled){await refreshVirtualFarm();if(result.order){const done=opsData?.orders.find(o=>o.id===result.order.id);if(done)result.order=done}}if(status.pending?.length){result.virtual_pending=status.pending;}if(status.pending?.length)setTimeout(()=>toast(status.pending[0]),0)}catch(e){setTimeout(()=>toast('Виртуальный садовник: '+e.message),0)}}return result};
async function loadVirtualGardener(){if(!account||virtualGardenerLoading)return;const uid=account.id;virtualGardenerLoading=true;try{const state=await apiBeforeVirtual('virtual-gardener');if(account?.id!==uid)return;virtualGardenerState=state;virtualGardenerUser=uid;if(state.enabled){const tick=await apiBeforeVirtual('virtual-gardener-tick',{});await refreshVirtualFarm()}render()}catch(e){toast('Режим садовника: '+e.message)}finally{virtualGardenerLoading=false}}
function virtualGardenerSettings(){const enabled=!!virtualGardenerState?.enabled;formAsync('Виртуальный садовник',`<div class="simple-action-symbol">👩‍🌾</div><p>${enabled?'Включён: демозадания исполняются сразу, урожай мгновенно созревает.':'Можно включить для проверки полного пути выращивания.'}</p><p>Демоработы и установки оплачиваются демобалансом автоматически по указанной цене. При нехватке средств или достижении лимита выполнение остановится.</p><p>Физических работ, настоящего урожая и вызова курьера нет. Перед реальным запуском отключите этот режим.</p><button class="btn">${enabled?'Выключить виртуального садовника':'Включить виртуального садовника'}</button>`,async()=>{virtualGardenerState=await apiBeforeVirtual('virtual-gardener-config',{enabled:!enabled});if(!enabled){await apiBeforeVirtual('virtual-gardener-tick',{});await refreshVirtualFarm()}modal.close();toast(enabled?'Виртуальный садовник отключён':'Виртуальный садовник включён')})}
farmViews.add(()=>{
 if(!account){document.querySelector('.virtual-gardener-badge')?.remove();virtualGardenerState=null;virtualGardenerUser=null;return}if(virtualGardenerUser!==account.id&&!virtualGardenerLoading)queueMicrotask(loadVirtualGardener);
 document.querySelector('.virtual-gardener-badge')?.remove();if(virtualGardenerState?.enabled){document.body.insertAdjacentHTML('beforeend','<button class="virtual-gardener-badge" onclick="virtualGardenerSettings()">👩‍🌾 Виртуальный садовник · мгновенный деморежим <span>Настроить</span></button>')}
 if(location.hash==='#settings'){document.querySelector('.profile-room')?.insertAdjacentHTML('beforeend',`<button class="virtual-room-switch" onclick="virtualGardenerSettings()">👩‍🌾 Виртуальный садовник · ${virtualGardenerState?.enabled?'вкл':'выкл'}</button>`)}
});

const warehouseBeforeVirtualGuard=warehousePage;
warehousePage=function(){if(account&&lifeData&&!hasStorage())return `<section class="panel"><h1>Здесь будет ваш склад</h1><p>Арендуйте хранение, чтобы пользоваться кладовой и холодильником. Без склада урожай можно отправить домой.</p><button class="btn" onclick="openStorageSlot()">Арендовать склад</button><button class="btn light" onclick="bedJourneyBasket()">Оформить доставку</button><a class="btn light" href="#home">← В хозяйство</a></section>`;return warehouseBeforeVirtualGuard()};
